"css": "\n:scope { container: qarg / inline-size; }\n.qa-dock { border-bottom: 1px solid var(--2b26d772-f6fe-4213-aec3-fc5154ba4ba6); }\n.qa-dock-in { display: grid; grid-template-columns: 6rem var(--dock-days, minmax(0, 1fr)); column-gap: 24px; padding-top: 16px; padding-bottom: 16px; }\n.qa-lanes, .qa-day { display: grid; grid-template-rows: 22px repeat(var(--lanes, 3), 20px) 22px; row-gap: 4px; min-width: 0; }\n.qa-lanes { grid-column: 1; }\n.qa-lane { grid-row: var(--row); align-self: center; }\n.qa-days { grid-column: 2 / -1; display: grid; grid-template-columns: subgrid; min-width: 0; }\n.qa-day + .qa-day { border-left: 5px solid var(--1767628f-ac49-439f-a591-09de91a3bb9b); padding-left: 24px; }\n.qa-name { grid-row: 1; }\n.qa-blocks {\n\tgrid-row: 2 / -2; display: grid; grid-template-rows: subgrid; grid-template-columns: repeat(var(--cols, 144), minmax(0, 1fr));\n\tmargin: 0; padding: 0; list-style: none;\n\tbackground-image: linear-gradient(to right, var(--2b26d772-f6fe-4213-aec3-fc5154ba4ba6) 1px, transparent 1px); background-size: calc(100% / var(--hours, 12)) 100%;\n}\n.qa-b { grid-column: var(--a) / var(--b); grid-row: var(--lane); margin-right: 2px; }\n.qa-b[data-kind=\"talk\"] { box-shadow: inset 0 0 0 1px var(--1767628f-ac49-439f-a591-09de91a3bb9b); }\n.qa-b[data-kind=\"workshop\"] { background-color: var(--1767628f-ac49-439f-a591-09de91a3bb9b); }\n.qa-b[data-kind=\"social\"] { background-color: var(--c50ffd2e-c171-4e5d-ba9c-04d111217d07); opacity: 0.45; }\n.qa-b[data-kind=\"break\"] { background-color: var(--2b26d772-f6fe-4213-aec3-fc5154ba4ba6); }\n.qa-b[data-on=\"true\"] { background-color: var(--8c73f435-9fcb-47b2-83c1-5c5a0cb0aaa7); box-shadow: none; opacity: 1; }\n.qa-marks { grid-row: -2 / -1; display: flex; justify-content: space-between; padding-top: 4px; }\n.qa-claims { padding-top: 40px; }\n.qa-claim { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); column-gap: 32px; row-gap: 16px; align-content: center; padding-top: 96px; padding-bottom: 96px; }\n.qa-claim + .qa-claim { padding-top: 40px; }\n.qa-fit { grid-column: 1 / -1; grid-row: 1; }\n.qa-by { grid-column: 1 / 9; grid-row: 2; }\n.qa-when { grid-column: 9 / 13; grid-row: 2; justify-self: end; justify-items: end; text-align: right; }\n.qa-claim:nth-child(even) .qa-fit, .qa-claim:nth-child(even) .qa-by { grid-column: 4 / -1; }\n.qa-claim:nth-child(even) .qa-when { grid-column: 1 / 4; grid-row: 1; align-self: end; justify-self: start; justify-items: start; text-align: left; padding-bottom: 12px; }\n@container qarg (max-width: 860px) {\n\t.qa-dock-in { grid-template-columns: 4.5rem var(--dock-days, minmax(0, 1fr)); column-gap: 16px; }\n\t.qa-day + .qa-day { padding-left: 16px; }\n\t.qa-claim { padding-top: 64px; padding-bottom: 64px; }\n\t.qa-claim + .qa-claim { padding-top: 24px; }\n\t.qa-by, .qa-claim:nth-child(even) .qa-fit, .qa-claim:nth-child(even) .qa-by { grid-column: 1 / -1; }\n\t.qa-when, .qa-claim:nth-child(even) .qa-when { grid-column: 1 / -1; grid-row: 3; justify-self: start; justify-items: start; text-align: left; padding-bottom: 0; }\n}\n/* phones: both days, one above the other */\n@container qarg (max-width: 560px) {\n\t.qa-dock-in { grid-template-columns: minmax(0, 1fr); padding-top: 12px; padding-bottom: 12px; }\n\t.qa-lanes { display: none; }\n\t.qa-days { grid-column: 1; display: flex; flex-direction: column; gap: 12px; }\n\t.qa-day { grid-template-rows: 22px repeat(var(--lanes, 3), 12px) 22px; }\n\t.qa-day + .qa-day { border-left: 0; padding-left: 0; }\n\t.qa-claim { grid-template-columns: minmax(0, 1fr); column-gap: 0; padding-top: 40px; padding-bottom: 40px; }\n\t.qa-claim + .qa-claim { padding-top: 24px; }\n}\n"
