def day_span(rows, key, iso, start, split, mins):
	latest = -1
	for raw in rows:
		parts = split(raw, 7)
		if parts[0].lower() not in [key.lower(), iso.lower()]:
			continue
		finish = mins(parts[2])
		if finish > latest:
			latest = finish
	if latest <= start * 60:
		return start * 60 + 60
	return ((latest + 59) // 60) * 60

lanes = []
days = []
claims = []
try:
	start = int(number(props.get("start_hour"), 9))
	rows = as_list(props.get("sessions"))
	room_cols = {}
	for raw in as_list(props.get("rooms")):
		parts = split_row(raw, 2)
		room_cols[parts[0].lower()] = len(lanes) + 1
		lanes.append({"label": parts[1] or parts[0], "row": str(len(lanes) + 2)})
	isos = {}
	lit = []
	for raw in as_list(props.get("claims")):
		parts = split_row(raw, 5)
		if not parts[0]:
			continue
		lit.append(parts[0].lower())
		claims.append(parts)
	fr = []
	for raw in as_list(props.get("days")):
		parts = split_row(raw, 2)
		key = parts[0]
		iso = parts[1]
		isos[key.lower()] = iso
		end = day_span(rows, key, iso, start, split_row, minutes)
		hours = (end - start * 60) // 60
		step = 1
		for candidate in [4, 3, 5, 2, 6]:
			if hours % candidate == 0 and hours // candidate <= 4:
				step = candidate
				break
		marks = []
		h = start
		while h * 60 <= end:
			marks.append({"label": clock(h * 60)})
			h = h + step
		blocks = []
		for raw in rows:
			cols = split_row(raw, 7)
			if cols[0].lower() not in [key.lower(), iso.lower()]:
				continue
			begin = minutes(cols[1])
			finish = minutes(cols[2])
			if begin < start * 60 or finish <= begin:
				continue
			place = cols[3].lower()
			if place in ["", "all", "every room", "everywhere"]:
				lane = "1 / -1"
			elif place in room_cols:
				lane = str(room_cols[place])
			else:
				continue
			kind = cols[6].lower()
			if kind not in ["talk", "workshop", "social", "break"]:
				kind = "talk"
			blocks.append({
				"a": str((begin - start * 60) // 5 + 1),
				"b": str((min(finish, end) - start * 60) // 5 + 1),
				"lane": lane,
				"kind": kind,
				"on": "true" if cols[4].lower() in lit else "false",
			})
		named = weekday(iso)
		fr.append("minmax(0, " + str(hours) + "fr)")
		days.append({
			"name": (named["name"] + " " + named["date"]).strip() or key,
			"cols": str(hours * 12),
			"hours": str(hours),
			"marks": marks,
			"blocks": blocks,
		})
	out = []
	for parts in claims:
		when = parts[3].split(" ")
		key = when[0].lower() if len(when) > 0 else ""
		at = when[1] if len(when) > 1 else ""
		iso = isos.get(key, "")
		named = weekday(iso)
		label = named["name"]
		if not label and len(when) > 0:
			label = when[0]
		out.append({
			"title": parts[0],
			"w": str(ems(parts[0], SIX)),
			"speaker": parts[1],
			"studio": parts[2],
			"when": (label + " " + at).strip(),
			"datetime": (iso + "T" + at) if iso and at else "",
			"room": parts[4],
		})
	claims = out
	component.dock_days = " ".join(fr)
	component.lanes_n = str(max(1, len(lanes)))
except:
	lanes = []
	days = []
	claims = []
	component.dock_days = "minmax(0, 1fr)"
	component.lanes_n = "3"
component.lanes = lanes
component.days = days
component.claims = claims
